def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], coords: np.ndarray, demand: np.ndarray, distance_matrix: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.
    Args:
        archive: A list of tuples, where each tuple contains:
            - solution: A list of numpy arrays, each representing a vehicle route. 
                        Each route starts and ends at the depot (node index 0), e.g., [0, 3, 5, 0].
            - objective: A tuple of two float values (total_distance, makespan), 
                        representing the two objective values of the solution.

        coords: A numpy array of shape (n_nodes, 2), representing (x, y) coordinates of each node (depot + customers).
        demand: A numpy array of shape (n_nodes,), where demand[i] is the demand of node i. The depot has demand 0.
        distance_matrix: A numpy array of shape (n_nodes, n_nodes), where [i][j] is the Euclidean distance between node i and j.
        capacity: A float representing the maximum capacity of each vehicle.

    Returns:
        A new neighbor solution.
    """
    archive_sorted = sorted(archive, key=lambda x: (-x[1][1], x[1][0]))
    selected_idx = min(len(archive_sorted) // 2, len(archive_sorted) - 1)
    base_solution = archive_sorted[selected_idx][0].copy()

    if len(base_solution) < 1:
        return base_solution

    all_nodes = []
    node_to_route = {}
    for route_idx, route in enumerate(base_solution):
        for node in route[1:-1]:
            all_nodes.append(node)
            node_to_route[node] = route_idx

    if len(all_nodes) < 2:
        return base_solution

    demand_threshold = capacity * 0.6
    clusters = []
    current_cluster = []

    for node in all_nodes:
        current_cluster.append(node)
        cluster_demand = np.sum(demand[current_cluster])

        if cluster_demand > capacity:
            current_cluster.pop()
            if len(current_cluster) > 0:
                clusters.append(current_cluster)
            current_cluster = [node]

    if len(current_cluster) > 0:
        clusters.append(current_cluster)

    if len(clusters) < 2:
        return base_solution

    new_routes = []
    for cluster in clusters:
        cluster_demand = np.sum(demand[cluster])
        if cluster_demand <= capacity:
            new_route = [0] + cluster + [0]
            new_routes.append(np.array(new_route))

    if len(new_routes) < 1:
        return base_solution

    new_solution = []
    for route in base_solution:
        if not any(np.array_equal(route, new_route) for new_route in new_routes):
            new_solution.append(route)

    new_solution.extend(new_routes)

    for i in range(len(new_solution)):
        for j in range(i + 1, len(new_solution)):
            route1, route2 = new_solution[i], new_solution[j]
            if len(route1) < 3 or len(route2) < 3:
                continue

            merged_route = np.concatenate((route1[:-1], route2[1:]))
            merged_demand = np.sum(demand[merged_route[1:-1]])

            if merged_demand <= capacity * 0.8:
                original_dist = np.sum(distance_matrix[route1[:-1], route1[1:]]) + np.sum(distance_matrix[route2[:-1], route2[1:]])
                merged_dist = np.sum(distance_matrix[merged_route[:-1], merged_route[1:]])

                if merged_dist < original_dist * 0.95:
                    new_solution = [route for idx, route in enumerate(new_solution) if idx not in {i, j}]
                    new_solution.append(merged_route)
                    break

    for route in new_solution:
        for i in range(1, len(route)-1):
            node = route[i]
            if demand[node] > demand_threshold:
                for other_route in new_solution:
                    if np.array_equal(other_route, route):
                        continue
                    for j in range(1, len(other_route)):
                        if np.sum(demand[other_route[1:-1]]) + demand[node] <= capacity:
                            temp_route = np.insert(other_route, j, node)
                            temp_dist = np.sum(distance_matrix[temp_route[:-1], temp_route[1:]])
                            original_dist = np.sum(distance_matrix[other_route[:-1], other_route[1:]])

                            if temp_dist < original_dist:
                                other_route[:] = temp_route
                                route = np.delete(route, i)
                                break

    return new_solution

