def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], coords: np.ndarray, demand: np.ndarray, distance_matrix: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.
    Args:
        archive: A list of tuples, where each tuple contains:
            - solution: A list of numpy arrays, each representing a vehicle route. 
                        Each route starts and ends at the depot (node index 0), e.g., [0, 3, 5, 0].
            - objective: A tuple of two float values (total_distance, makespan), 
                        representing the two objective values of the solution.

        coords: A numpy array of shape (n_nodes, 2), representing (x, y) coordinates of each node (depot + customers).
        demand: A numpy array of shape (n_nodes,), where demand[i] is the demand of node i. The depot has demand 0.
        distance_matrix: A numpy array of shape (n_nodes, n_nodes), where [i][j] is the Euclidean distance between node i and j.
        capacity: A float representing the maximum capacity of each vehicle.

    Returns:
        A new neighbor solution.
    """
    archive_sorted = sorted(archive, key=lambda x: (x[1][1], -x[1][0]), reverse=True)
    selected_idx = min(len(archive_sorted) // 4, len(archive_sorted) - 1)
    base_solution = archive_sorted[selected_idx][0].copy()

    if len(base_solution) < 2:
        return base_solution

    all_customers = []
    for route in base_solution:
        all_customers.extend(route[1:-1])

    if not all_customers:
        return base_solution

    demands = demand[all_customers]
    coords_customers = coords[all_customers]

    demand_threshold = capacity * random.uniform(0.5, 0.8)
    high_demand_customers = [i for i, d in enumerate(demands) if d > demand_threshold]
    low_demand_customers = [i for i, d in enumerate(demands) if d <= demand_threshold]

    cluster_centers = []
    for _ in range(min(3, len(all_customers))):
        cluster_centers.append(random.choice(all_customers))

    clusters = {i: [] for i in range(len(cluster_centers))}
    for i, customer in enumerate(all_customers):
        distances = [np.linalg.norm(coords[customer] - coords[center]) for center in cluster_centers]
        closest = np.argmin(distances)
        clusters[closest].append(customer)

    super_clusters = []
    for cluster_id, customers in clusters.items():
        if not customers:
            continue

        super_cluster = []
        current_demand = 0
        for customer in sorted(customers, key=lambda x: np.linalg.norm(coords[x] - coords[cluster_centers[cluster_id]])):
            if current_demand + demand[customer] <= capacity:
                super_cluster.append(customer)
                current_demand += demand[customer]
            else:
                if super_cluster:
                    super_clusters.append(super_cluster)
                super_cluster = [customer]
                current_demand = demand[customer]
        if super_cluster:
            super_clusters.append(super_cluster)

    new_routes = []
    for super_cluster in super_clusters:
        if not super_cluster:
            continue

        route = [0] + super_cluster + [0]
        if np.sum(demand[super_cluster]) <= capacity:
            new_routes.append(np.array(route))
        else:
            split_points = [0]
            current_demand = 0
            for i, customer in enumerate(super_cluster):
                current_demand += demand[customer]
                if current_demand > capacity * random.uniform(0.7, 0.9) or i == len(super_cluster) - 1:
                    split_points.append(i + 1)
                    current_demand = 0

            for j in range(len(split_points) - 1):
                segment = super_cluster[split_points[j]:split_points[j+1]]
                if segment:
                    new_routes.append(np.array([0] + segment + [0]))

    if not new_routes:
        return base_solution

    balanced_routes = []
    remaining_customers = set(all_customers)
    for route in new_routes:
        customers_in_route = set(route[1:-1])
        remaining_customers -= customers_in_route
        balanced_routes.append(route)

    while remaining_customers:
        customer = remaining_customers.pop()
        best_route = None
        best_increase = float('inf')

        for i, route in enumerate(balanced_routes):
            if np.sum(demand[route[1:-1]]) + demand[customer] <= capacity:
                increase = distance_matrix[route[-2], customer] + distance_matrix[customer, 0] - distance_matrix[route[-2], 0]
                if increase < best_increase:
                    best_increase = increase
                    best_route = i

        if best_route is not None:
            new_route = np.concatenate((balanced_routes[best_route][:-1], [customer], [0]))
            balanced_routes[best_route] = new_route
        else:
            balanced_routes.append(np.array([0, customer, 0]))

    return balanced_routes
